package com.brightloop.payment;
import com.brightloop.invoice.*;import java.math.BigDecimal;import java.time.Instant;import java.util.UUID;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;
@Service public class PaymentService {
 private final PaymentRepository payments;private final InvoiceRepository invoices;private final com.brightloop.notification.EmailNotificationService emails;public PaymentService(PaymentRepository p,InvoiceRepository i,com.brightloop.notification.EmailNotificationService emails){payments=p;invoices=i;this.emails=emails;}
 @Transactional(readOnly=true) public java.util.List<Response> list(){return payments.findAll().stream().sorted(java.util.Comparator.comparing(Payment::getPaymentDate).reversed()).map(Response::of).toList();}
 @Transactional(readOnly=true) public java.util.List<Response> listForCustomer(String email){return payments.findByCustomerEmailIgnoreCase(email).stream().sorted(java.util.Comparator.comparing(Payment::getPaymentDate).reversed()).map(Response::of).toList();}
 @Transactional(readOnly=true) public Response get(Long id){return Response.of(payments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Payment not found")));}
 @Transactional(readOnly=true) public Response getForCustomer(Long id,String email){var p=payments.findById(id).filter(x->x.getCustomer().getEmail().equalsIgnoreCase(email)).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Payment not found"));return Response.of(p);}
 @Transactional public Response record(Request r){var invoice=invoices.findForUpdate(r.invoiceId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Invoice not found"));if(invoice.getOutstanding().signum()<=0)throw new ResponseStatusException(HttpStatus.CONFLICT,"Invoice is already fully paid");if(r.amount().compareTo(invoice.getOutstanding())>0)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Payment cannot exceed the outstanding balance");if(!"CONFIRMED".equals(invoice.getStatus())&& !"PARTIALLY_PAID".equals(invoice.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"This invoice cannot accept a payment");var payment=payments.save(new Payment("PAY-"+UUID.randomUUID().toString().substring(0,12).toUpperCase(),invoice,r.amount(),r.paymentMethod(),r.transactionReference(),r.notes()));invoice.applyPayment(r.amount());emails.payment(invoice.getCustomer().getEmail(),payment.getPaymentNumber(),r.amount().toPlainString());return Response.of(payment);}
 public record Request(@jakarta.validation.constraints.NotNull Long invoiceId,@jakarta.validation.constraints.NotNull @jakarta.validation.constraints.DecimalMin(value="0.01") BigDecimal amount,@jakarta.validation.constraints.Pattern(regexp="CARD|BANK_TRANSFER|CASH|UPI|OTHER") String paymentMethod,String transactionReference,String notes){}
 public record Response(Long id,String paymentNumber,Long invoiceId,String invoiceNumber,Long customerId,String customerName,BigDecimal amount,String paymentMethod,String transactionReference,Instant paymentDate,String status){public static Response of(Payment p){return new Response(p.getId(),p.getPaymentNumber(),p.getInvoice().getId(),p.getInvoice().getInvoiceNumber(),p.getCustomer().getId(),p.getCustomer().getFullName(),p.getAmount(),p.getPaymentMethod(),p.getTransactionReference(),p.getPaymentDate(),p.getStatus());}}
}
